    }
    if (c.status !== 'OPEN' || deferred(c, this.session.sheetToday())) {
      this.setRowError(c.id, `Only an OPEN claim that is not deferred can be part-settled.`);
      return;
    }
    if (inClosedPeriod(this.periods.list(), c.dueBy)) {
